export class TokenInfo {
  symbol: string;
  mint: Address;
  mintDecimals: number;

  constructor(symbol: string, mint: Address, mintDecimal: number) {
    this.symbol = symbol;
    this.mint = mint;
    this.mintDecimals = mintDecimal;
  }
}

export function removeComputeBudgetProgram(ixs: Instruction[]): Instruction[] {
  const filteredIxs = ixs.filter((ix) => {
    if (ix.programAddress === COMPUTE_BUDGET_PROGRAM_ADDRESS) {
      return false;
    }
    return true;
  });
  return filteredIxs;
}

export function removeSetupIxs(ixs: Instruction[]): Instruction[] {
  const filteredIxs = ixs.filter((ix) => {
    if (
      ix.programAddress === ASSOCIATED_TOKEN_PROGRAM_ADDRESS ||
      ix.programAddress === SYSTEM_PROGRAM_ADDRESS ||
      ix.programAddress === TOKEN_PROGRAM_ADDRESS ||
      ix.programAddress === TOKEN_2022_PROGRAM_ADDRESS
    ) {
      return false;
    }
    return true;
  });
  return filteredIxs;
}

export async function parseKeypairFile(file: string): Promise<KeyPairSigner> {
  const keypairFile = require('fs').readFileSync(file);
  const keypairBytes = new Uint8Array(JSON.parse(keypairFile.toString()));

  const keypair = await createKeyPairFromBytes(keypairBytes);

  return createSignerFromKeyPair(keypair);
}

export function divCeil(a: BN, b: BN): BN {
  return a.add(b).sub(new BN(1)).div(b);
}

export function amountToLamportsBN(amount: Decimal, decimals: number): BN {
  let factor = Math.pow(10, decimals);
  return new BN(amount.mul(factor).floor().toString());
}

export function amountBNToLamportsBN(amount: BN, decimals: number): BN {
  let factor = new BN(Math.pow(10, decimals));
  return new BN(amount.mul(factor).toString());
}

export function amountToLamportsDecimal(amount: Decimal, decimals: number): Decimal {
  let factor = Math.pow(10, decimals);
  return amount.mul(factor);
}

export function lamportsToAmountBN(amount: BN, decimals: number): Decimal {
  let factor = new BN(Math.pow(10, decimals));
  return new Decimal(amount.div(factor).toString());
}

export function lamportsToAmountDecimal(amount: Decimal, decimals: number): Decimal {
  let factor = Math.pow(10, decimals);
  return amount.div(factor);
}

export async function getMintDecimals(connection: Rpc<SolanaRpcApi>, mint: Address): Promise<number> {
  let info = await fetchMint(connection, mint);
  return info.data.decimals;
}

export async function printMultisigTx(tx: Transaction) {
  console.log(getBase58Decoder().decode(tx.messageBytes));
}

export async function printSimulateTx(conn: Rpc<SolanaRpcApi>, tx: Transaction) {
  console.log(
    'Tx in B64',
    `https://explorer.solana.com/tx/inspector?message=${encodeURIComponent(
      Buffer.from(tx.messageBytes).toString('base64'),
    )}`,
  );

  let res = await conn
    .simulateTransaction(getBase64EncodedWireTransaction(tx), {
      encoding: 'base64',
    })
    .send();
  console.log('Simulate Response', res);
  console.log('');
}

export async function checkIfAccountExists(connection: Rpc<SolanaRpcApi>, account: Address): Promise<boolean> {
  const acc = await fetchEncodedAccount(connection, account);
  return acc.exists;
}

export async function getAssociatedTokenAddress(
  ownerAddress: Address,
  tokenMintAddress: Address,
  tokenProgramAddress: Address = TOKEN_PROGRAM_ADDRESS,
): Promise<Address> {
  const [associatedTokenAddress] = await findAssociatedTokenPda({
    mint: tokenMintAddress,
    owner: ownerAddress,
    tokenProgram: tokenProgramAddress,
  });
  return associatedTokenAddress;
}

export async function createAssociatedTokenAccountIdempotentInstruction(
  owner: Address,
  mint: Address,
  payer: TransactionSigner,
  tokenProgramAddress: Address = TOKEN_PROGRAM_ADDRESS,
  ata?: Address,
): Promise<[Address, Instruction]> {
  let ataAddress = ata;
  if (!ataAddress) {
    ataAddress = await getAssociatedTokenAddress(owner, mint, tokenProgramAddress);
  }
  const idempotentCreateUserTokenAccountIx = getCreateAssociatedTokenIdempotentInstruction(
    {
      payer,
      ata: ataAddress,
      mint,
      owner,
      tokenProgram: tokenProgramAddress,
      systemProgram: SYSTEM_PROGRAM_ADDRESS,
    },
    { programAddress: ASSOCIATED_TOKEN_PROGRAM_ADDRESS },
  );
  return [ataAddress, idempotentCreateUserTokenAccountIx];
}

export async function createAtaIdempotent(
  user: Address,
  payer: TransactionSigner,
  mint: Address,
  mintTokenProgramAddress: Address = TOKEN_PROGRAM_ADDRESS,
): Promise<{ ata: Address; createAtaIx: Instruction }> {
  const [ata, createAtaIx] = await createAssociatedTokenAccountIdempotentInstruction(
    user,
    mint,
    payer,
    mintTokenProgramAddress,
  );

  return { ata, createAtaIx };
}

export async function getTokenAccountBalance(conn: Rpc<SolanaRpcApi>, tokenAccount: Address): Promise<Decimal> {
  const tokenAccountBalance = await conn.getTokenAccountBalance(tokenAccount).send();
  return new Decimal(tokenAccountBalance.value.amount).div(Decimal.pow(10, tokenAccountBalance.value.decimals));
}

export async function getSolBalanceInLamports(conn: Rpc<SolanaRpcApi>, account: Address): Promise<Lamports> {
  let balance: Lamports | undefined = undefined;
  while (balance === undefined) {
    balance = (await conn.getAccountInfo(account).send()).value?.lamports;
  }
  return balance;
}

export async function getSolBalance(conn: Rpc<SolanaRpcApi>, account: Address): Promise<Decimal> {
  const balance = new Decimal(await getSolBalanceInLamports(conn, account));
  return lamportsToAmountDecimal(balance, 9);
}

export type Cluster = 'localnet' | 'devnet' | 'mainnet';
export type SolEnv = {
  cluster: Cluster;
  ownerKeypairPath: string;
  endpoint: string;
};

export function endpointFromCluster(cluster: string | undefined): string {
  switch (cluster) {
    case 'mainnet':
      return 'FIXTHIS';
    case 'devnet':
      return 'FIXTHIS';
    case 'localnet':
      return 'http://127.0.0.1:8899';
  }

  if (cluster) {
    return cluster;
  }

  return 'err';
}

export function u16ToBytes(num: number) {
  const arr = new ArrayBuffer(2);
  const view = new DataView(arr);
  view.setUint16(0, num, false);
  return new Uint8Array(arr);
}

export function buildTransactionMessage(
  ixns: Instruction[],
  payer: Address,
  blockhash: BlockhashWithExpiry,
  addressLookupTables?: Account<AddressLookupTable>[],
): CompilableTransactionMessage {
  const transactionMessage = pipe(
    createTransactionMessage({ version: 0 }),
    (tx) => setTransactionMessageFeePayer(payer, tx),
    (tx) => appendTransactionMessageInstructions(ixns, tx),
    (tx) => setTransactionMessageLifetimeUsingBlockhash(blockhash, tx),
  );

  if (addressLookupTables) {
    const compressedTransactionMessage = compressTransactionMessageUsingAddressLookupTables(
      transactionMessage,
      transformFromLookupTableAccounts(addressLookupTables),
    );
    return compressedTransactionMessage;
  }
  return transactionMessage;
}

export function buildCompiledTransaction(
  ixns: Instruction[],
  payer: Address,
  blockhash: BlockhashWithExpiry,
  addressLookupTables?: Account<AddressLookupTable>[],
): Transaction & TransactionWithLifetime {
  const transactionMessage = buildTransactionMessage(ixns, payer, blockhash, addressLookupTables);
  return compileTransaction(transactionMessage);
}

export async function executeTransaction(
  rpc: Rpc<SolanaRpcApi>,
  rpcWs: RpcSubscriptions<SolanaRpcSubscriptionsApi>,
  ixns: Instruction[],
  signer: TransactionSigner,
  extraSigners: TransactionSigner[] = [],
): Promise<string> {
  const { value: latestBlockhash } = await rpc.getLatestBlockhash().send();

  const transactionMessage = pipe(
    createTransactionMessage({ version: 0 }),
    (tx) => setTransactionMessageFeePayerSigner(signer, tx),
    (tx) => setTransactionMessageLifetimeUsingBlockhash(latestBlockhash, tx),
    (tx) => appendTransactionMessageInstructions(ixns, tx),
  );

  const transactionsMessageWithSigners = extraSigners.length
    ? addSignersToTransactionMessage(extraSigners, transactionMessage)
    : transactionMessage;

  const signedTransaction = await signTransactionMessageWithSigners(transactionsMessageWithSigners);

  await sendAndConfirmTransactionFactory({ rpc, rpcSubscriptions: rpcWs })(signedTransaction, {
    commitment: 'confirmed',
  });
  return getSignatureFromTransaction(signedTransaction);
}

export function sleep(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export const getEnvOrDefault = (envVarName: string, defaultValue: string): string => {
  if (envVarName in process.env) {
    return process.env[envVarName] as string;
  }
  return defaultValue;
};

export function compareUint8Arrays(arr1: Uint8Array, arr2: Uint8Array): boolean {
  if (arr1.length !== arr2.length) {
    return false;
  }
  for (let i = 0; i < arr1.length; i++) {
    if (arr1[i] !== arr2[i]) {
      return false;
    }
  }
  return true;
}

export async function getMintsProgramOwner(connection: Rpc<SolanaRpcApi>, mint: Address): Promise<Address> {
  const mintAccount = await connection.getAccountInfo(mint).send();

  if (!mintAccount.value) {
    throw new Error('Mint not found');
  }
  return mintAccount.value.owner;
}

// Helper function to create a timeout promise
function createTimeout(ms: number): Promise<never> {
  return new Promise((_, reject) => {
    setTimeout(() => {
      reject(new Error(`Request timed out after ${ms}ms`));
    }, ms);
  });
}

// Function to wrap a promise with a timeout
export async function withTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  loggerCallback: () => any,
): Promise<T | null> {
  try {
    return await Promise.race([promise, createTimeout(timeoutMs)]);
  } catch (error) {
    if (error instanceof Error && error.message.includes('timed out')) {
      loggerCallback();
      return null; // Return null for timed-out routes
    }
    throw error; // Re-throw other errors
  }
}

export async function withAtLeastOneTimeout<T>(
  promises: PromiseWithName<T>[],
  atLeastOneNoMoreThanTimeoutMS: number,
  initialTimeoutMs: number,
  logger: Logger,
): Promise<(T | null)[]> {
  return new Promise((resolve) => {
    const results: (T | null)[] = new Array(promises.length).fill(null);
    const completedPromises = new Set<number>();
    let completedCount = 0;
    let initialTimeoutExpired = false;
    let finalTimeoutExpired = false;

    const hasValidRoute = () => {
      return results.some(
        (result) => result !== null && result !== undefined && Array.isArray(result) && result.length > 0,
      );
    };

    const logIncompletePromises = (timeoutType: string) => {
      const incompletePromises = promises
        .map((promiseWithName, index) => ({ name: promiseWithName.name, index }))
        .filter(({ index }) => !completedPromises.has(index))
        .map(({ name }) => name);

      if (incompletePromises.length > 0) {
        logger.warn(`${timeoutType} timeout: Incomplete promises: ${incompletePromises.join(', ')}`);
      }
    };

    const checkAndResolve = () => {
      if (finalTimeoutExpired || (initialTimeoutExpired && hasValidRoute())) {
        resolve(results);
      }
    };

    promises.forEach((promise, index) => {
      promise.promise
        .then((result) => {
          if (!finalTimeoutExpired) {
            results[index] = result;
            completedPromises.add(index);
            completedCount++;

            if (completedCount === promises.length) {
              finalTimeoutExpired = true;
              resolve(results);
            } else {
              checkAndResolve();
            }
          }
        })
        .catch((error) => {
          if (!finalTimeoutExpired) {
            // Log router errors for debugging but don't fail the entire operation
            results[index] = null;
            completedPromises.add(index);
            completedCount++;

            if (completedCount === promises.length) {
              finalTimeoutExpired = true;
              resolve(results);
            } else {
              checkAndResolve();
            }
          }
        });
    });

    // Initial timeout (smaller, e.g., 700ms)
    setTimeout(() => {
      if (!finalTimeoutExpired) {
        initialTimeoutExpired = true;
        logger.info(`Initial timeout expired after ${initialTimeoutMs}ms`);
        logIncompletePromises('Initial');
        checkAndResolve();
      }
    }, initialTimeoutMs);

    // Final timeout (larger, e.g., 2000ms) - only used if we got at least one result
    setTimeout(() => {
      if (!finalTimeoutExpired) {
        finalTimeoutExpired = true;
        logger.info(`Final timeout expired after ${atLeastOneNoMoreThanTimeoutMS}ms`);
        logIncompletePromises('Final');
        resolve(results);
      }
    }, atLeastOneNoMoreThanTimeoutMS);
  });
}

