export async function getLookupTablesFromLutApi(mintAddresses: Address[]): Promise<Address[]> {
  try {
    const response = await axios.post<FindMinimalLUTResponse>(
      'https://api.kamino.finance/luts/find-minimal',
      {
        addresses: mintAddresses,
        verify: true,
      } as FindMinimalLUTRequest,
      {
        headers: {
          'Content-Type': 'application/json',
        },
      },
    );

    if (!response.data || !Array.isArray(response.data)) {
      return [];
    }

    return response.data.map((addr) => address(addr));
  } catch (error) {
    if (axios.isAxiosError(error)) {
      console.error('API Error:', error.response?.data || error.message);
      throw new Error(`Failed to find minimal LUT addresses: ${error.message}`);
    }
    throw error;
  }
}

export function getAccountsNotInLookupTables(
  lookupTables: Account<AddressLookupTable>[],
  instructions: Instruction[],
): Address[] {
  // Create a set of all accounts in lookup tables for fast lookup
  const lookupTableAccounts = new Set<string>();
  for (const lookupTable of lookupTables) {
    for (const account of lookupTable.data.addresses) {
      lookupTableAccounts.add(account);
    }
  }

  const accountsNotInLookupTables = new Set<string>();

  for (const instruction of instructions) {
    // Skip associated token program instructions to avoid user atas
    if (instruction.programAddress === ASSOCIATED_TOKEN_PROGRAM_ADDRESS) {
      continue;
    }

    for (const accountMeta of instruction.accounts ?? []) {
      const accountKey = accountMeta.address;

      if (!lookupTableAccounts.has(accountKey)) {
        accountsNotInLookupTables.add(accountKey);
      }
    }
  }

  return Array.from(accountsNotInLookupTables).map((key) => address(key));
}

export function pick<T extends object, K extends keyof T>(obj: T, keys: K[]): Pick<T, K> {
  const result = {} as Pick<T, K>;
  for (const key of keys) {
    if (key in obj) {
      result[key] = obj[key];
    }
  }
  return result;
}
